"""Página mostrada no navegador depois do retorno do login (`sk auth login`).

Autocontida: sem recursos externos, sem scripts. O símbolo da marca é embutido em base64, e a
política de conteúdo (CSP) só permite estilo e imagem embutidos. Não repete nenhum valor
recebido do provedor: na recusa, mostra só uma mensagem fixa.
"""

# Conteúdo de apresentação com linhas longas (base64 e CSS): só este arquivo ignora E501.
from typing import Final

LOGO_PNG_BASE64: Final = ""

_STYLE = """
:root { color-scheme: light; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center;
  background: #fafafa; color: #111111;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif; }
main { width: min(92vw, 460px); background: #ffffff; border-radius: 16px; padding: 44px 36px;
  box-shadow: 0 1px 2px rgba(0,0,0,.06), 0 8px 24px rgba(0,0,0,.06); text-align: center; }
.brand { display: flex; justify-content: center; margin-bottom: 32px; }
.brand img { width: 230px; max-width: 70vw; height: auto; }
.badge { width: 64px; height: 64px; border-radius: 50%; margin: 0 auto 20px;
  display: grid; place-items: center; }
.ok { background: #e3f5ea; color: #1f9d55; }
.fail { background: #fdecec; color: #c62828; }
h1 { font-size: 22px; margin: 0 0 8px; font-weight: 650; }
p { margin: 0; font-size: 15px; line-height: 1.5; color: #4b5b52; }
.hint { margin-top: 24px; padding-top: 20px; border-top: 1px solid #e6ebe8; font-size: 13px;
  color: #6b7b72; }
@media (prefers-color-scheme: dark) {
  :root { color-scheme: dark; }
  body { background: #0f1512; color: #e6efe9; }
  main { background: #17201b; box-shadow: none; }
  p, .hint { color: #a9bbb0; }
  .hint { border-top-color: #26332b; }
  .ok { background: #173a25; color: #7fd49c; }
  .fail { background: #3d1d1d; color: #ff8a80; }
}
"""

_ICON_OK = (
    '<svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
    'stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
    '<polyline points="5 12.5 10 17.5 19 7.5"/></svg>'
)
_ICON_FAIL = (
    '<svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
    'stroke-width="2.4" stroke-linecap="round" aria-hidden="true">'
    '<line x1="6" y1="6" x2="18" y2="18"/><line x1="18" y1="6" x2="6" y2="18"/></svg>'
)

CONTENT_SECURITY_POLICY = "default-src 'none'; style-src 'unsafe-inline'; img-src data:"


def render_callback_page(*, success: bool) -> bytes:
    """Página de sucesso ou de recusa. Os textos são fixos, sem dados do provedor."""
    brand = (
        f'<div class="brand"><img alt="Smarkee" src="data:image/png;base64,{LOGO_PNG_BASE64}">'
        "</div>"
    )
    if success:
        body = (
            f'<div class="badge ok">{_ICON_OK}</div>'
            "<h1>Login completed</h1>"
            "<p>Your session was authorized. You can go back to the terminal.</p>"
        )
        title = "Login completed · sk"
    else:
        body = (
            f'<div class="badge fail">{_ICON_FAIL}</div>'
            "<h1>Login not completed</h1>"
            "<p>The login was refused or cancelled. Go back to the terminal and run "
            "<strong>sk auth login</strong> again.</p>"
        )
        title = "Login not completed · sk"
    hint = '<p class="hint">You can close this window.</p>'
    page = (
        '<!doctype html><html lang="en"><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1">'
        f"<title>{title}</title><style>{_STYLE}</style></head>"
        f"<body><main>{brand}{body}{hint}</main></body></html>"
    )
    return page.encode("utf-8")
